const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/product_inventory.xlsx');
const sheet = wb.Sheets['Products'];
const data = XLSX.utils.sheet_to_json(sheet, {header: 1});

// Update headers to include new columns
data[0] = [
  'Product ID', 'Name', 'Category', 'Price', 'In Stock',
  'Brand', 'Subcategory', 'Stock Quantity', 'Rating', 'Review Count',
  'Shipping Days', 'Gift Wrap Available', 'Warranty (Months)',
  'Return Window (Days)', 'Restocking Fee (%)', 'Backorder Available',
  'Compatible With', 'Variants', 'Description'
];

// Fill empty values for existing rows in new columns
for (let i = 1; i < data.length; i++) {
  while (data[i].length < data[0].length) {
    data[i].push('');
  }
}

// Add PROD-2028EE row
data.push([
  'PROD-2028EE',
  'Magnetic Wireless Charging Stand',
  'electronics',
  45,
  'Yes',
  'VoltForge',
  'Mobile Accessories',
  96,
  3.9,
  459,
  3,
  'Yes',
  12,
  30,
  0,
  'No',
  'None listed',
  'None',
  'New magnetic wireless charging stand in black for Qi-enabled phones with up to 15W charging. Physical goods accessory with taxable retail pricing and inventory tracking enabled.'
]);

// Create new sheet from updated data
const newSheet = XLSX.utils.aoa_to_sheet(data);

// Auto-size columns
const colWidths = data[0].map((_, colIdx) => {
  const maxLen = data.reduce((max, row) => {
    const val = row[colIdx] != null ? String(row[colIdx]) : '';
    return Math.max(max, val.length);
  }, 0);
  return { wch: Math.min(maxLen + 2, 50) };
});
newSheet['!cols'] = colWidths;

wb.Sheets['Products'] = newSheet;
XLSX.writeFile(wb, '/workspace/testbed/data/product_inventory.xlsx');
console.log('File updated successfully.');

